public class SplitterCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(Splitter impl) {
        try {
            return SplitterChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectSplitter()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectSplitter()));
        check("rejects the drops-trailing-empty-field bug", false, verdict(new DropsTrailingFieldSplitter()));
        check("rejects the does-not-trim bug", false, verdict(new NoTrimSplitter()));
        check("rejects the crash-on-empty-input bug", false, verdict(new CrashOnEmptySplitter()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectSplitter implements Splitter {
    public java.util.List<String> split(String csv) {
        java.util.List<String> out = new java.util.ArrayList<>();
        for (String field : csv.split(",", -1)) out.add(field.trim());
        return out;
    }
}

class AlsoCorrectSplitter implements Splitter {
    public java.util.List<String> split(String csv) {
        java.util.List<String> out = new java.util.ArrayList<>();
        int start = 0;
        int comma = csv.indexOf(',', start);
        while (comma >= 0) {
            out.add(csv.substring(start, comma).trim());
            start = comma + 1;
            comma = csv.indexOf(',', start);
        }
        out.add(csv.substring(start).trim());
        return out;
    }
}

class DropsTrailingFieldSplitter implements Splitter {
    public java.util.List<String> split(String csv) {
        java.util.List<String> out = new java.util.ArrayList<>();
        for (String field : csv.split(",")) out.add(field.trim());
        return out;
    }
}

class NoTrimSplitter implements Splitter {
    public java.util.List<String> split(String csv) {
        java.util.List<String> out = new java.util.ArrayList<>();
        for (String field : csv.split(",", -1)) out.add(field);
        return out;
    }
}

class CrashOnEmptySplitter implements Splitter {
    public java.util.List<String> split(String csv) {
        boolean trailingEmpty = csv.charAt(csv.length() - 1) == ',';
        java.util.List<String> out = new java.util.ArrayList<>();
        for (String field : csv.split(",", -1)) out.add(field.trim());
        if (trailingEmpty && !out.get(out.size() - 1).isEmpty()) out.add("");
        return out;
    }
}

