/**
 * TASK: Write the checks that decide whether a Splitter is correct.
 *
 * The Splitter contract:
 *   split(csv) breaks csv at every comma and returns the fields in order.
 *   Each field is TRIMMED of leading and trailing spaces.
 *   Empty fields are KEPT, including a trailing one:
 *       split("a,b,c")   -> ["a", "b", "c"]
 *       split(" a , b ") -> ["a", "b"]
 *       split("a,b,")    -> ["a", "b", ""]
 *       split(",")       -> ["", ""]
 *       split("a")       -> ["a"]
 *       split("")        -> [""]        (one field, which is the empty string)
 *   The input is never null.
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. One broken implementation THROWS on
 * the empty input, so a crash counts as a failure: wrap your calls in try/catch
 * and return false if anything is thrown.
 *
 * CAREFUL: a list holding one empty string prints as [] -- exactly like an empty
 * list. Compare size() and get(i) instead of trusting toString().
 */
interface Splitter {
    /* Provided -- do not edit. */
    java.util.List<String> split(String csv);
}

public class SplitterChecker {

    public static boolean isCorrect(Splitter impl) {
        try {
            if (!matches(impl.split("a,b,c"), "a", "b", "c")) return false;
            if (!matches(impl.split(" a , b "), "a", "b")) return false;
            if (!matches(impl.split("a,b,"), "a", "b", "")) return false;
            if (!matches(impl.split(","), "", "")) return false;
            if (!matches(impl.split("a"), "a")) return false;
            if (!matches(impl.split(""), "")) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }

    private static boolean matches(java.util.List<String> actual, String... expected) {
        if (actual == null || actual.size() != expected.length) return false;
        for (int i = 0; i < expected.length; i++) {
            if (!expected[i].equals(actual.get(i))) return false;
        }
        return true;
    }
}
